const tables: Record<Exclude<Locale, "en">, TranslationTable> = {
  ar: { ...ar, ...arPageCopy },
  fr: { ...fr, ...frPageCopy },
};

export function translate(locale: Locale, source: string): string {
  if (locale === "en") return source;
  const table = tables[locale];
  return table[source] ?? table[source.replace(/\s+/g, " ").trim()] ?? source;
}

export function translateMany(locale: Locale, values: string[]): string[] {
  return values.map((value) => translate(locale, value));
}
